<?php
/** Proof: recipes, the editor and versions (recipes.md "Proof": Recipes, The editor, Versions). */
require __DIR__ . '/lib.php';
$w = recipes_world();
[$jd, ] = sign_on(30);   // Dana, Chef at Downtown
[$jb, ] = sign_on(28);   // Bea, Kitchen at Downtown
$since = last_activity_id();

echo "1. Recipes — created with their first drafts, the CHECKs' sentences, codes, locks, archive\n";
$r = post_json($jd, '/recipes/save.php', ['name' => 'SMOKE Stock', 'kind' => 'prep', 'batch_yield_qty' => 4, 'batch_yield_unit' => 'l', 'expected_loss_pct' => 10]);
ok($r['code'] === 422 && str_contains($r['body'], 'A prep recipe names'), "a prep without an output ingredient is refused with the CHECK's sentence ({$r['code']})");
$r = post_json($jd, '/recipes/save.php', ['name' => 'SMOKE Salad', 'kind' => 'menu_item', 'output_ingredient' => $w['stock']]);
ok($r['code'] === 422, 'a menu item with an output ingredient is refused (' . $r['code'] . ')');
$r = post_json($jd, '/recipes/save.php', ['name' => 'SMOKE Stock', 'kind' => 'prep', 'output_ingredient' => $w['stock'], 'batch_yield_qty' => 4, 'batch_yield_unit' => 'l', 'expected_loss_pct' => 10]);
ok($r['code'] === 200 && $r['json']['ok'] === true && !empty($r['json']['version_id']) && str_starts_with($r['json']['location'], '/recipes/versions/' . $r['json']['version_id']), 'the stock is made with its first draft; record_id and the editor as the location');
$stock = (int) $r['json']['record_id']; $stockV = (int) $r['json']['version_id'];
ok(one('SELECT code FROM recipes WHERE id = :id', ['id' => $stock]) === 'R-SMOKE_STOCK', 'the code R-SMOKE_STOCK was made from the name');
ok((bool) one('SELECT is_prep FROM ingredients WHERE id = :i', ['i' => $w['stock']]), 'the output ingredient is flagged is_prep');
ok(one('SELECT c.key FROM recipes r JOIN menu_categories c ON c.id = r.category_id WHERE r.id = :id', ['id' => $stock]) === 'prep', "a prep defaults to the 'prep' menu category");
$r = post_json($jd, '/recipes/save.php', ['name' => 'SMOKE Sandwich', 'kind' => 'menu_item', 'menu_category' => 'mains', 'portion_qty' => 220, 'portion_unit' => 'g', 'method' => "Grill the chicken.\n\nAssemble."]);
ok($r['code'] === 200 && $r['json']['ok'], 'the sandwich is made (category by key, a portion, a method)');
$sand = (int) $r['json']['record_id']; $sandV = (int) $r['json']['version_id'];
$r = post_json($jd, '/recipes/save.php', ['name' => 'SMOKE Extra chicken', 'kind' => 'modifier']);
ok($r['code'] === 200 && one('SELECT code FROM recipes WHERE id = :id', ['id' => (int) $r['json']['record_id']]) === 'M-SMOKE_EXTRA_CHICKEN', 'a modifier gets the M- code');
$mod = (int) $r['json']['record_id']; $modV = (int) $r['json']['version_id'];
$r = post_json($jd, '/recipes/save.php', ['name' => 'SMOKE Stock 2', 'kind' => 'prep', 'output_ingredient' => $w['stock'], 'code' => 'R-SMOKE_STOCK']);
ok($r['code'] === 422 && stripos($r['body'], 'taken') !== false, 'a typed duplicate code is refused in words');
$r = post_json($jd, '/recipes/save.php', ['recipe' => $sand, 'name' => 'SMOKE Chicken sandwich']);
ok($r['code'] === 200 && one('SELECT name FROM recipes WHERE id = :id', ['id' => $sand]) === 'SMOKE Chicken sandwich', 'recipe_update renames');
$r = post_json($jd, '/recipes/save.php', ['recipe' => $sand, 'lines' => '[]']);
ok($r['code'] === 422 && str_contains($r['body'], 'recipe_line_set'), 'lines on an update point at recipe_line_set');
$r = post_json($jd, '/recipes/save.php', ['recipe' => 'R-SMOKE_STOCK', 'method' => 'Simmer.']);
ok($r['code'] === 200, 'a recipe param accepts the code');
$a = activity('recipe.create', $since); $u = activity('recipe.update', $since);
ok(count($a) === 3 && (int) $a[0]['recipe_id'] === $stock && (int) $a[0]['scope_id'] === 101 && str_contains((string) $a[0]['after'], '"version_id"'), 'recipe.create logged three times with recipe_id, scope_id and the first version');
ok(count($u) >= 2 && !str_contains((string) end($u)['after'], 'Simmer'), "recipe.update logged; the method's words are not in the payload");

echo "2. The editor — lines through the trigger, the conversion sentence, refusals, Pattern C, the batch\n";
$r = page($jd, '/recipes/versions/' . $stockV);
ok($r['code'] === 200 && has($r, 'id="editor"') && has($r, 'id="editor-add-row"') && has($r, 'id="line-form-field-ingredient-picker"') && has($r, 'id="line-form-field-sub-recipe-picker"') && has($r, 'id="editor-cost"') && has($r, 'id="activate-form"') && has($r, 'id="version-form"'), 'the editor: the add row with both pickers, the cost panel, the activation form, the batch form');
$r = page($jd, '/recipes/' . $stock . '/versions/' . $stockV);
ok($r['code'] === 200 && has($r, 'id="editor"') && has($r, 'data-version-id="' . $stockV . '"'), "the manifest's shape /recipes/{recipe}/versions/{version} routes to the same editor (the child-record rewrite)");
$r = page($jd, '/recipes/convert?ingredient=' . $w['chicken'] . '&qty=2&unit=kg');
ok($r['code'] === 200 && has($r, '2 kg = 2 000 g') && has($r, 'data-ok="1"'), 'the conversion sentence: 2 kg = 2 000 g');
$r = page($jd, '/recipes/convert?ingredient=' . $w['gin'] . '&qty=1.5&unit=floz');
ok(has($r, '1.5 floz = 44.36 ml'), '1.5 floz of gin = 44.36 ml');
$r = page($jd, '/recipes/convert?ingredient=' . $w['lime'] . '&qty=100&unit=g');
ok(has($r, 'data-ok="0"') && has($r, 'each-weight'), 'limes in grams: the sentence in danger says they have no each-weight');
$r = page($jd, '/recipes/convert?sub_recipe=' . $stock . '&qty=50&unit=ml');
ok(has($r, '50 ml = 50 ml'), 'a prep sub-recipe converts through its output ingredient');
$r = page($jd, '/recipes/convert?sub_recipe=' . $mod . '&qty=1&unit=portion');
ok(has($r, '1 portion of'), 'a modifier sub-recipe says "1 portion of …"');
$r = page($jd, '/recipes/line-units?ingredient=' . $w['egg']);
ok(preg_match_all('/<option value="(flat|case|each|dozen|g|kg)"/', $r['body']) >= 5, "the unit select for eggs: its own units (flat, case), each and dozen, and the weight units through the each-weight");
$r = page($jd, '/recipes/line-units?sub_recipe=' . $mod);
ok(has($r, 'value="portion"') && !has($r, 'value="g"'), 'a modifier sub-recipe offers portion alone');
$r = post_json($jd, '/recipes/versions/line.php', ['version' => $stockV, 'ingredient' => $w['chicken'], 'qty' => 2, 'unit' => 'kg']);
ok($r['code'] === 200 && $r['json']['ok'] && (float) one('SELECT qty_base FROM recipe_lines WHERE id = :id', ['id' => (int) $r['json']['record_id']]) === 2000.0, "a line of 2 kg lands as qty_base 2 000 by the trigger ({$r['code']})");
$l1 = (int) $r['json']['record_id'];
$r = post_json($jd, '/recipes/versions/line.php', ['version' => $stockV, 'ingredient' => $w['lime'], 'qty' => 1, 'unit' => 'g']);
ok($r['code'] === 422 && str_contains($r['body'], 'each-weight'), "limes in grams: the save is refused with the trigger's sentence");
$r = post_json($jd, '/recipes/versions/line.php', ['version' => $sandV, 'ingredient' => $w['chicken'], 'qty' => 170, 'unit' => 'g', 'line_yield_pct' => 90]);
ok($r['code'] === 200, 'the sandwich: 170 g of chicken at a 90 % line yield');
$sl1 = (int) $r['json']['record_id'];
$r = post_json($jd, '/recipes/versions/line.php', ['version' => $sandV, 'sub_recipe' => $stock, 'qty' => 50, 'unit' => 'ml']);
ok($r['code'] === 200 && (float) one('SELECT qty_base FROM recipe_lines WHERE id = :id', ['id' => (int) $r['json']['record_id']]) === 50.0, "the stock as a sub-recipe: 50 ml → qty_base 50 (its output's base)");
$r = post_json($jd, '/recipes/versions/line.php', ['version' => $sandV, 'ingredient' => $w['egg'], 'qty' => 1, 'unit' => 'each']);
ok($r['code'] === 200, 'one egg');
$r = post_json($jd, '/recipes/versions/line.php', ['version' => $sandV, 'sub_recipe' => $mod, 'qty' => 1, 'unit' => 'g']);
ok($r['code'] === 422 && str_contains($r['body'], 'portions'), 'a modifier sub-recipe in grams is refused: taken in portions');
$r = post_json($jd, '/recipes/versions/line.php', ['version' => $sandV, 'ingredient' => $w['egg'], 'sub_recipe' => $mod, 'qty' => 1, 'unit' => 'each']);
ok($r['code'] === 422 && str_contains($r['body'], 'not both'), 'a line naming both an ingredient and a recipe is refused');
$r = post_json($jd, '/recipes/versions/line.php', ['version' => $sandV, 'qty' => 1, 'unit' => 'each']);
ok($r['code'] === 422, 'a line naming neither is refused');
$r = post_json($jd, '/recipes/versions/line.php', ['version' => $sandV, 'ingredient' => 'SMK-EGG', 'qty' => 0, 'unit' => 'each']);
ok($r['code'] === 422 && isset($r['json']['error']['fields']['qty']), 'a zero quantity is refused naming the field');
$r = post_json($jd, '/recipes/versions/line.php', ['line' => $sl1, 'qty' => 180]);
ok($r['code'] === 200 && (float) one('SELECT qty FROM recipe_lines WHERE id = :id', ['id' => $sl1]) === 180.0 && (float) one('SELECT qty_base FROM recipe_lines WHERE id = :id', ['id' => $sl1]) === 180.0, 'a line edited in place: the quantity and its base follow');
$r = req('POST', '/recipes/versions/line.php', ['jar' => $jd, 'headers' => ['HX-Request: true'], 'form' => ['csrf_token' => page_csrf($jd), 'line' => $sl1, 'qty' => 170]]);
ok($r['code'] === 200 && has($r, 'id="editor-line-row-' . $sl1 . '"') && preg_match('/HX-Trigger: recipeChanged/i', $r['headers']), 'Pattern C: the HTMX save answers the row partial with HX-Trigger recipeChanged');
$r = post_json($jd, '/recipes/versions/line.php', ['version' => $sandV, 'ingredient' => $w['lettuce'], 'qty' => 30, 'unit' => 'g', 'group_name' => 'garnish', 'optional' => 'yes', 'notes' => 'shredded']);
ok($r['code'] === 200, 'an optional garnish line with a group and notes');
$garnish = (int) $r['json']['record_id'];
$r = post_json($jd, '/recipes/versions/line-remove.php', ['line' => $garnish]);
ok($r['code'] === 200 && one('SELECT count(*) FROM recipe_lines WHERE id = :id', ['id' => $garnish]) === 0, 'a line removed');
ok(count(activity('recipe.line_remove', $since)) === 1 && str_contains((string) activity('recipe.line_remove', $since)[0]['before'], '"qty_base"'), 'recipe.line_remove logged with the line before');
$ids = array_column(q('SELECT id FROM recipe_lines WHERE version_id = :v ORDER BY seq', ['v' => $sandV]), 'id');
$r = req('POST', '/recipes/versions/reorder.php', ['jar' => $jd, 'headers' => ['HX-Request: true'], 'form' => ['csrf_token' => page_csrf($jd), 'version' => $sandV, 'lines' => array_reverse($ids)]]);
ok($r['code'] === 204 && (int) one('SELECT seq FROM recipe_lines WHERE id = :id', ['id' => (int) end($ids)]) === 1, 'the rows reordered by drag → seq');
$r = post_json($jd, '/recipes/versions/save.php', ['version' => $stockV, 'batch_yield_qty' => 4, 'batch_yield_unit' => 'l', 'expected_loss_pct' => 10, 'change_note' => 'the first']);
ok($r['code'] === 200 && one('SELECT batch_yield_unit_code FROM recipe_versions WHERE id = :v', ['v' => $stockV]) === 'l', "the batch form saves the yield in the output's unit and the loss");
$r = post_json($jd, '/recipes/versions/save.php', ['version' => $stockV, 'batch_yield_unit' => 'kg']);
ok($r['code'] === 422 || one('SELECT batch_yield_unit_code FROM recipe_versions WHERE id = :v', ['v' => $stockV]) === 'kg', 'a unit of another class is accepted only when the ingredient bridges it (the verb refuses at activation otherwise)');
post_json($jd, '/recipes/versions/save.php', ['version' => $stockV, 'batch_yield_unit' => 'l']);
$r = page($jd, '/recipes/versions/' . $sandV . '/cost');
ok($r['code'] === 200 && has($r, 'id="editor-cost-portion"') && preg_match('/editor-cost-portion">\$([0-9.]+)/', $r['body'], $m), 'the cost panel for Dana shows the cost per portion');
$r = page($jb, '/recipes/versions/' . $sandV . '/cost');
ok($r['code'] === 200 && has($r, 'id="editor-cost-withheld"') && !has($r, 'id="editor-cost-portion"'), 'the cost panel for Bea says "cost withheld" and never calls the function');
ok(page($jb, '/recipes/versions/' . $sandV)['code'] === 403, 'Bea (Kitchen) cannot open the editor (403)');
$a = activity('recipe.line_set', $since);
ok(count($a) >= 5 && str_contains((string) $a[0]['after'], '"qty_base"') && (int) $a[0]['recipe_id'] === $stock, 'recipe.line_set logged with qty_base and recipe_id');

echo "3. Versions — activation with effective dates, the preview, one draft, immutability, discard, retire, allergens\n";
$r = post_json($jd, '/recipes/versions/activate.php', ['version' => $modV]);
ok($r['code'] === 422 && str_contains($r['body'], 'no lines'), 'an empty draft is refused');
post_json($jd, '/recipes/versions/line.php', ['version' => $modV, 'ingredient' => $w['chicken'], 'qty' => 85, 'unit' => 'g']);
post_json($jd, '/recipes/versions/save.php', ['version' => $stockV, 'batch_yield_unit' => '']);
$r = post_json($jd, '/recipes/versions/activate.php', ['version' => $stockV]);
ok($r['code'] === 422 && str_contains($r['body'], 'batch yield names a unit'), "a prep without a batch unit is refused in the verb's words");
post_json($jd, '/recipes/versions/save.php', ['version' => $stockV, 'batch_yield_unit' => 'l']);
$r = page($jd, '/recipes/activate-preview?version=' . $stockV . '&from=' . date('Y-m-d', strtotime('-30 days')));
ok(has($r, 'first version') && has($r, 'data-ok="1"'), 'the preview says v1 is the first version');
$r = post_json($jd, '/recipes/versions/activate.php', ['version' => $stockV, 'effective_from' => date('Y-m-d', strtotime('-30 days'))]);
ok($r['code'] === 200 && $r['json']['ended_version_no'] === null && one('SELECT status FROM recipe_versions WHERE id = :v', ['v' => $stockV]) === 'active', 'the stock activated 30 days back');
$r = post_json($jd, '/recipes/versions/activate.php', ['version' => $sandV, 'effective_from' => date('Y-m-d', strtotime('-20 days'))]);
ok($r['code'] === 200, 'the sandwich activated 20 days back');
post_json($jd, '/recipes/versions/activate.php', ['version' => $modV, 'effective_from' => date('Y-m-d', strtotime('-20 days'))]);
ok(one('SELECT allergens_rollup FROM recipes WHERE id = :r', ['r' => $sand]) === '{egg}', "allergens roll up: {egg} on the sandwich");
ok(one('SELECT allergens FROM ingredients WHERE id = :i', ['i' => $w['stock']]) === '{}', "the stock's output ingredient inherits none");
$r = post_json($jd, '/recipes/versions/line.php', ['version' => $stockV, 'ingredient' => $w['flour'], 'qty' => 1, 'unit' => 'g']);
ok($r['code'] === 422 && str_contains($r['body'], 'only while it is a draft'), "an active version's line save is refused");
$r = post_json($jd, '/recipes/versions/save.php', ['version' => $stockV, 'batch_yield_qty' => 5]);
ok($r['code'] === 422 && str_contains($r['body'], 'new version carries the change'), 'an active version is immutable: a new version carries the change');
$r = post_json($jd, '/recipes/versions/draft.php', ['recipe' => $stock, 'change_note' => 'more chicken']);
ok($r['code'] === 200 && (int) one('SELECT count(*) FROM recipe_lines WHERE version_id = :v', ['v' => (int) $r['json']['version_id']]) === 1, 'a new draft of the stock copies its line');
$stockV2 = (int) $r['json']['version_id'];
$r = post_json($jd, '/recipes/versions/draft.php', ['recipe' => $stock]);
ok($r['code'] === 422 && str_contains($r['body'], 'draft already exists'), 'a second draft is refused');
$r = page($jd, '/recipes/' . $stock);
ok(has($r, 'id="recipe-view-edit-draft"') && !has($r, 'id="recipe-view-new-draft"'), 'the page offers "Edit the draft" and no "New draft" while one exists');
$line = (int) one('SELECT id FROM recipe_lines WHERE version_id = :v', ['v' => $stockV2]);
post_json($jd, '/recipes/versions/line.php', ['line' => $line, 'qty' => 2.5]);
$r = post_json($jd, '/recipes/versions/line.php', ['version' => $stockV2, 'sub_recipe' => $sand, 'qty' => 1, 'unit' => 'portion']);
ok($r['code'] === 422 && str_contains($r['body'], 'may not contain itself'), 'the sandwich as a sub-recipe of the stock: "may not contain itself" (a cycle)');
$tomorrow = date('Y-m-d', strtotime('+1 day'));
$r = page($jd, '/recipes/activate-preview?version=' . $stockV2 . '&from=' . $tomorrow);
ok(has($r, 'v1 ends ' . format_date($tomorrow)) && has($r, 'v2 is in force from'), 'the preview: v1 ends tomorrow; v2 is in force from tomorrow');
$r = post_json($jd, '/recipes/versions/activate.php', ['version' => $stockV2, 'effective_from' => date('Y-m-d', strtotime('-40 days'))]);
ok($r['code'] === 422 && str_contains($r['body'], 'later date'), "a date before v1's start is refused in words");
$r = post_json($jd, '/recipes/versions/activate.php', ['version' => $stockV2, 'effective_from' => $tomorrow]);
ok($r['code'] === 200 && (int) $r['json']['ended_version_no'] === 1, 'v2 activated from tomorrow; the reply says v1 ends');
ok((int) one('SELECT ri_recipe_version_on(:r, current_date)', ['r' => $stock]) === $stockV && (int) one('SELECT ri_recipe_version_on(:r, current_date + 1)', ['r' => $stock]) === $stockV2, 'today v1 is in force, tomorrow v2');
$r = page($jd, '/recipes/' . $stock);
ok(has($r, 'id="version-chip-' . $stockV . '"') && has($r, 'id="version-chip-' . $stockV2 . '"') && preg_match('/version-chip-' . $stockV2 . '"[^>]*>v2 · ' . preg_quote(format_date($tomorrow), '/') . ' – \(in force\)/', $r['body']), 'the version strip shows both with their dates');
$a = activity('recipe.version_activate', $since);
ok(count($a) === 4 && (int) (json_decode((string) end($a)['after'], true)['ended_version_no'] ?? 0) === 1, 'recipe.version_activate logged with ended_version_no');
$r = post_json($jd, '/recipes/versions/draft.php', ['recipe' => $sand]);
$d = (int) $r['json']['version_id'];
$r = post_json($jd, '/recipes/versions/discard.php', ['version' => $d]);
ok($r['code'] === 200 && one('SELECT count(*) FROM recipe_versions WHERE id = :v', ['v' => $d]) === 0 && one('SELECT count(*) FROM recipe_lines WHERE version_id = :v', ['v' => $d]) === 0, 'a draft discarded, its lines gone');
$r = post_json($jd, '/recipes/versions/discard.php', ['version' => $sandV]);
ok($r['code'] === 422 && str_contains($r['body'], 'Only a draft'), 'an active version is not discarded');
$r = post_json($jd, '/recipes/save.php', ['name' => 'SMOKE Soup', 'kind' => 'menu_item', 'lines' => json_encode([['ingredient' => $w['stock'], 'qty' => 300, 'unit' => 'ml']])]);
$soup = (int) $r['json']['record_id']; $soupV = (int) $r['json']['version_id'];
post_json($jd, '/recipes/versions/activate.php', ['version' => $soupV, 'effective_from' => date('Y-m-d', strtotime('-10 days'))]);
$r = post_json($jd, '/recipes/versions/retire.php', ['version' => $soupV, 'effective_to' => date('Y-m-d')]);
ok($r['code'] === 200 && one('SELECT ri_recipe_version_on(:r, current_date + 1)', ['r' => $soup]) === null && (int) one('SELECT ri_recipe_version_on(:r, current_date)', ['r' => $soup]) === $soupV, 'a version retired from today: none in force tomorrow, still today');
$r = page($jd, '/recipes/?q=soup');
ok(has($r, 'recipe-card-' . $soup . '-version') && (has($r, 'retired') || has($r, 'v1 since')), "the soup's card after retirement");
$r = post_json($jd, '/recipes/save.php', ['recipe' => $sand, 'kind' => 'prep', 'output_ingredient' => $w['stock']]);
ok($r['code'] === 422 && str_contains($r['body'], 'locked'), 'kind is locked after activation (the handler\'s sentence)');
$r = post_json($jd, '/recipes/archive.php', ['recipe' => $soup]);
ok($r['code'] === 200 && !(bool) one('SELECT active FROM recipes WHERE id = :r', ['r' => $soup]), 'archived');
$r = post_json($jd, '/recipes/archive.php', ['recipe' => $soup, 'archived' => 'no']);
ok($r['code'] === 200 && (bool) one('SELECT active FROM recipes WHERE id = :r', ['r' => $soup]), 'and restored');
ok(count(activity('recipe.archive', $since)) === 2, 'recipe.archive logged twice');

echo "4. The cards, the filters, the page\n";
$r = page($jd, '/recipes/');
ok($r['code'] === 200 && has($r, 'id="recipe-list-group-menu_item"') && has($r, 'id="recipe-list-group-prep"') && has($r, 'id="recipe-list-group-modifier"') && has($r, 'id="recipe-card-' . $sand . '"'), 'the cards grouped by kind');
ok(has($r, 'id="recipe-card-' . $sand . '-version"') && preg_match('/recipe-card-' . $sand . '-version">v1 since/', $r['body']) && preg_match('/recipe-card-' . $sand . '-cost">\s*<span class="fw-semibold">\$/', $r['body']), "the sandwich's card: the version chip and the cost per portion (Dana sees it)");
$r = page($jb, '/recipes/');
ok($r['code'] === 200 && has($r, 'title="cost withheld"') && !preg_match('/recipe-card-' . $sand . '-cost">\s*<span class="fw-semibold">\$/', $r['body']), 'Bea sees the cards with the cost withheld');
$r = page($jd, '/recipes/?kind=prep');
ok(has($r, 'recipe-card-' . $stock . '"') && !has($r, 'recipe-card-' . $sand . '"'), 'the kind filter');
$r = page($jd, '/recipes/?q=sandwich&category=' . one("SELECT id FROM menu_categories WHERE key = 'mains'"));
ok(has($r, 'recipe-card-' . $sand . '"') && !has($r, 'recipe-card-' . $stock . '"'), 'the search and the category filter');
$r = page($jd, '/recipes/?status=archived');
ok(!has($r, 'recipe-card-' . $sand . '"'), 'the status filter (none archived now)');
$r = page($jd, '/recipes/' . $sand);
ok($r['code'] === 200 && has($r, 'id="recipe-lines-table"') && has($r, 'id="recipe-tree"') && has($r, 'id="recipe-batch"') && has($r, 'id="recipe-method"') && has($r, 'id="recipe-menu-items"') && has($r, 'id="recipe-used-in"') && has($r, 'id="recipe-trail"') && has($r, 'data-entity="recipe"'), "the recipe's page: lines, the tree, the batch, the method, menu items, used in, the trail");
ok(preg_match('/id="recipe-leaves">One batch uses, in all:.*chicken/i', $r['body']) && has($r, '↳'), 'the tree names the sub-recipe and the leaves say what one batch uses in all');
$r = page($jd, '/recipes/' . $stock);
ok(has($r, 'id="used-in-' . $sand . '-1"'), 'the stock is "used in" the sandwich');
$r = page($jd, '/recipes/' . $sand . '?version=' . $sandV . '&as_of=' . date('Y-m-d', strtotime('-25 days')));
ok($r['code'] === 200 && has($r, 'costed as of ' . format_date(date('Y-m-d', strtotime('-25 days')))), '?as_of= re-costs the page at that date');
$r = page($jd, '/recipes/' . $stockV2 . '999');
ok($r['code'] === 404, 'an unknown recipe is 404');
finish();
